{"summary": "Fetch IMF DataMapper for real GDP level and inspect Georgia values", "command": "python3 - <<'PY'
import json, urllib.request

def fetch(ind):
    url=f'https://www.imf.org/external/datamapper/api/v1/{ind}/GEO'
    with urllib.request.urlopen(url, timeout=60) as f:
        return json.load(f)

data=fetch('NGDP_R')
geo=data['values']['NGDP_R']['GEO']
print('years',sorted(geo.keys())[-10:])
for y in ['2019','2020','2021','2022','2023','2024','2025','2026','2027']:
    print(y, geo.get(y))
PY"}

{"summary": "Test GDP deflator index series availability from IMF DataMapper", "command": "python3 - <<'PY'
import json, urllib.request
for ind in ['NGDP_D','NGDP_DPC','PCPI','PCPIPCH','PPPEX','ENDA_XDC_USD_RATE']:
    url=f'https://www.imf.org/external/datamapper/api/v1/{ind}/GEO'
    try:
        with urllib.request.urlopen(url, timeout=60) as f:
            data=json.load(f)
        print(ind,'values' in data)
        if 'values' in data:
            geo=data['values'][ind].get('GEO',{})
            yrs=sorted(geo.keys())
            print('  years',yrs[-5:])
    except Exception as e:
        print(ind,'ERROR',e)
PY"}

